# Surah Hud (chapter 11) — part 3: ayat 21-30 (IDs 1494-1503)
SURAH = 11

ENTRIES = {
1494: (
"یہی لوگ — ہیں — جنہوں نے — اپنی جان — کو — نقصان — میں — ڈالا — اور — ان سے — وہ چیز — گم ہو گئی — جو — وہ — گھڑتے تھے",
"""۱۔ ظالموں — نے اپنی جان — کو — نقصان پہنچایا۔
۲۔ ’’أُولَٰئِكَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ‘‘ — یہی لوگ — ہیں — جنہوں نے — اپنی جان — کو — نقصان — میں — ڈالا — اور — ان سے — وہ چیز — گم ہو گئی — جو — وہ — گھڑتے تھے — یعنی انہوں نے اپنی جان کو — نقصان — میں — ڈالا — اور ان سے — وہ — جھوٹ گم ہو گیا — جو — وہ — گھڑتے تھے۔
۳۔ عملی سبق: جھوٹ — آخرت میں — کوئی ساتھ نہیں دیتا۔"""
),
1495: (
"کوئی شک نہیں — وہ — آخرت — میں — سب سے زیادہ خسارہ اٹھانے والے — ہیں",
"""۱۔ آخرت — میں — سب سے زیادہ خسارہ — ظالموں کا۔
۲۔ ’’لَا جَرَمَ أَنَّهُمْ فِي الْآخِرَۃِ هُمُ الْأَخْسَرُونَ‘‘ — کوئی شک نہیں — وہ — آخرت — میں — سب سے زیادہ خسارہ اٹھانے والے — ہیں — یعنی آخرت میں — وہ — سب سے زیادہ خسارہ اٹھانے والے — ہیں۔
۳۔ عملی سبق: آخرت کی تیاری — کرو؛ دنیا — وقتی — ہے۔"""
),
1496: (
"بے شک — وہ لوگ — جو — ایمان لائے — اور — نیک عمل — کیے — اور — اپنے رب — کے سامنے — عاجزی کی — یہی لوگ — جنت والے — ہیں — وہ — اس میں — ہمیشہ — رہیں گے",
"""۱۔ ایمان، عمل صالح اور عاجزی — جنت — کی کنجی۔
۲۔ ’’إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَأَخْبَتُوا إِلَىٰ رَبِّهِمْ أُولَٰئِكَ أَصْحَابُ الْجَنَّۃِ هُمْ فِيهَا خَالِدُونَ‘‘ — بے شک — وہ لوگ — جو — ایمان لائے — اور — نیک عمل — کیے — اور — اپنے رب — کے سامنے — عاجزی کی — یہی لوگ — جنت والے — ہیں — وہ — اس میں — ہمیشہ — رہیں گے — یعنی ایمان، نیک عمل اور عاجزی — والے — جنت — والے ہیں۔
۳۔ عملی سبق: ایمان، عمل اور عاجزی — جنت — کی — کنجی ہے۔"""
),
1497: (
"دو — گروہوں — کی — مثال — ایسی ہے — جیسے — اندھا اور بہرا — اور دیکھنے والا اور سننے والا — کیا — یہ — دونوں — یکساں ہیں — کیا — تم — نصیحت نہیں لیتے",
"""۱۔ کالاثر — اور — بصیر — کی — مثال — سمجھیں۔
۲۔ ’’مَّثَلُ الْفَرِيقَيْنِ كَالْأَعْمَىٰ وَالْأَصَمِّ وَالْبَصِيرِ وَالسَّمِيعِ هَلْ يَسْتَوِيَانِ مَثَلًا أَفَلَا تَذَكَّرُونَ‘‘ — دو — گروہوں — کی — مثال — ایسی ہے — جیسے — اندھا اور بہرا — اور دیکھنے والا اور سننے والا — کیا — یہ — دونوں — یکساں ہیں — کیا — تم — نصیحت نہیں لیتے — یعنی اندھا اور بہرا — اور — بصیر اور سمیع — یکساں — نہیں ہیں؛ کیا تم — نصیحت — نہیں لیتے۔
۳۔ عملی سبق: بصیرت اور سماعت — اللہ کی نعمتیں ہیں؛ شکر کرو۔"""
),
1498: (
"اور — ہم نے — نوحؑ — کو — اپنی — قوم — کی طرف — بھیجا — بے شک — میں — تمہارے لیے — واضح ڈرانے والا — ہوں",
"""۱۔ نوحؑ — کی — بعثت۔
۲۔ ’’وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ إِنِّي لَكُمْ نَذِيرٌ مُّبِينٌ‘‘ — اور — ہم نے — نوحؑ — کو — اپنی — قوم — کی طرف — بھیجا — بے شک — میں — تمہارے لیے — واضح ڈرانے والا — ہوں — یعنی ہم نے — نوحؑ کو — ان کی قوم کی طرف — بھیجا — کہ — میں تمہارے لیے — واضح ڈرانے والا — ہوں۔
۳۔ عملی سبق: ہر قوم کو — واضح دلائل — ملے۔"""
),
1499: (
"یہ کہ — تم اللہ کے سوا — کسی کی عبادت — نہ کرو — بے شک — مجھے — تم پر — ایک دردناک دن کے عذاب — سے ڈرتا ہوں",
"""۱۔ نوحؑ — کا پیغام — صرف اللہ کی عبادت۔
۲۔ ’’أَنْ لَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ أَلِيمٍ‘‘ — یہ کہ — تم اللہ کے سوا — کسی کی عبادت — نہ کرو — بے شک — مجھے — تم پر — ایک دردناک دن کے عذاب — سے ڈرتا ہوں — یعنی نوحؑ نے کہا — اللہ کے سوا کسی کی عبادت نہ کرو؛ مجھے — تم پر — دردناک دن کے عذاب — سے — ڈرتا ہے۔
۳۔ عملی سبق: شرک — سب سے بڑا خطرہ — ہے؛ اس سے بچیں۔"""
),
1500: (
"پس — وہ لوگ — جو — اپنی قوم — میں — سے — کافر — تھے — ان کے سرداروں — نے — کہا — ہم — آپ کو — اپنے جیسا — ایک انسان — دیکھتے ہیں — اور — ہم — آپ کو دیکھتے ہیں — کہ — آپؐ — کی — پیروی — ان — لوگوں — نے — کی — جو — ہمارے — بدترین لوگ — ہیں — صرف — اپنی — ابتدائی سوچ — سے — اور — ہم — تمہارے — لیے — ہم — پر — کوئی فضیلت — نہیں دیکھتے — بلکہ — ہم — تمہارے — بارے میں — گمان کرتے ہیں — کہ — تم — جھوٹے ہو",
"""۱۔ سرداروں کی — طبقاتی سوچ — نوحؑ اور ان کے ساتھیوں — کو — حقیر — سمجھا۔
۲۔ ’’فَقَالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِن قَوْمِهِ مَا نَرَاكَ إِلَّا بَشَرًا مِّثْلَنَا وَمَا نَرَاكَ اتَّبَعَكَ إِلَّا الَّذِينَ هُمْ أَرَاذِلُنَا بَادِيَ الرَّأْيِ وَمَا نَرَىٰ لَكُمْ عَلَيْنَا مِن فَضْلٍ بَلْ نَظُنُّكُمْ كَاذِبِينَ‘‘ — پس — وہ لوگ — جو — اپنی قوم — میں — سے — کافر — تھے — ان کے سرداروں — نے — کہا — ہم — آپ کو — اپنے جیسا — ایک انسان — دیکھتے ہیں — اور — ہم — آپ کو دیکھتے ہیں — کہ — آپؐ — کی — پیروی — ان — لوگوں — نے — کی — جو — ہمارے — بدترین لوگ — ہیں — صرف — اپنی — ابتدائی سوچ — سے — اور — ہم — تمہارے — لیے — ہم — پر — کوئی فضیلت — نہیں دیکھتے — بلکہ — ہم — تمہارے — بارے میں — گمان کرتے ہیں — کہ — تم — جھوٹے ہو — یعنی سرداروں نے کہا — آپؐ تو ہمارے جیسا — انسان ہیں — آپؐ — کی — پیروی — ہمارے — بدترین لوگ — کر رہے ہیں — صرف اپنی ابتدائی سوچ کے مطابق — ہم تمہاری — کوئی فضیلت نہیں دیکھتے — بلکہ — ہم گمان کرتے ہیں — تم جھوٹے — ہو۔
۳۔ عملی سبق: لوگوں کی نظر — آپ — کی — ہدایت — پر اثر نہیں ڈالتی؛ حق — حق ہے۔"""
),
1501: (
"انہوں نے — کہا — اے میری قوم — بتاؤ — اگر — میں — اپنے رب کی طرف سے — دلیل — پر ہوں — اور — اس — نے — مجھے — اپنی — طرف سے — رحمت — دی — مگر — وہ — تم پر — پوشیدہ — ہو گئی — تو کیا — ہم — تمہیں — اسے — زبردستی — قبول — کروادیں — حالانکہ — تم — اسے ناپسند کرتے ہو",
"""۱۔ نوحؑ — قوم سے — دلائل — دیتے ہیں۔
۲۔ ’’قَالَ يَا قَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَۃٍ مِّن رَّبِّي وَآتَانِي رَحْمَۃً مِّنْ عِندِهِ فَعُمِّيَتْ عَلَيْكُمْ أَنُلْزِمُكُمُوهَا وَأَنتُمْ لَهَا كَارِهُونَ‘‘ — انہوں نے — کہا — اے میری قوم — بتاؤ — اگر — میں — اپنے رب کی طرف سے — دلیل — پر ہوں — اور — اس — نے — مجھے — اپنی — طرف سے — رحمت — دی — مگر — وہ — تم پر — پوشیدہ — ہو گئی — تو کیا — ہم — تمہیں — اسے — زبردستی — قبول — کروادیں — حالانکہ — تم — اسے ناپسند کرتے ہو — یعنی اگر میں — رب کی طرف سے دلیل — پر ہوں — اور وہ تم پر پوشیدہ — ہو گئی — تو کیا میں — تمہیں زبردستی — رحمت — دے دوں — حالانکہ — تم ناپسند کرتے ہو۔
۳۔ عملی سبق: ہدایت — زبردستی — نہیں آتی؛ دل سے — قبول — کرو۔"""
),
1502: (
"اور — اے میری قوم — میں — اس — پر — تم سے — کوئی مال — نہیں مانگتا — میرا — بدلہ — صرف اللہ — کے — ذمے ہے — اور — میں — ایمان لانے والوں — کو — دھکیلنے کے لیے — نہیں آیا — بے شک — وہ — اپنے رب — سے — ملنے والے — ہیں — لیکن — میں — تمہیں — ایک — نادان — قوم — سمجھتا ہوں",
"""۱۔ نوحؑ — اجرت — نہیں مانگتے؛ غریب مؤمنوں — کو — نہیں دھکیلتے۔
۲۔ ’’وَيَا قَوْمِ لَا أَسْأَلُكُمْ عَلَيْهِ مَالًا إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَمَا أَنَا بِطَارِدِ الَّذِينَ آمَنُوا إِنَّهُم مُّلَاقُو رَبِّهِمْ وَلَٰكِنِّي أَرَاكُمْ قَوْمًا تَجْهَلُونَ‘‘ — اور — اے میری قوم — میں — اس — پر — تم سے — کوئی مال — نہیں مانگتا — میرا — بدلہ — صرف اللہ — کے — ذمے ہے — اور — میں — ایمان لانے والوں — کو — دھکیلنے کے لیے — نہیں آیا — بے شک — وہ — اپنے رب — سے — ملنے والے — ہیں — لیکن — میں — تمہیں — ایک — نادان — قوم — سمجھتا ہوں — یعنی میں — تم سے — کوئی مال — نہیں مانگتا؛ میرا بدلہ — اللہ — کے ذمے ہے — اور میں مؤمنوں — کو دھکیلنے کے لیے — نہیں آیا؛ تم — ایک نادان قوم — ہو۔
۳۔ عملی سبق: حق کا پیغام — بلا — اجرت — دو — اور — مفلس — مؤمنوں — کو — دور — نہ کرو۔"""
),
1503: (
"اور — اے میری قوم — کون — اللہ کے مقابلے میں — میری مدد — کرے گا — اگر — میں — ان — کو — دھکیل دوں — کیا — تم — نصیحت — نہیں لیتے",
"""۱۔ مؤمنوں کو دھکیلنا — اللہ کی مدد — سے — محروم ہونے کے مترادف۔
۲۔ ’’وَيَا قَوْمِ مَن يَنصُرُنِي مِنَ اللَّهِ إِن طَرَدتُّهُمْ أَفَلَا تَذَكَّرُونَ‘‘ — اور — اے میری قوم — کون — اللہ کے مقابلے میں — میری مدد — کرے گا — اگر — میں — ان — کو — دھکیل دوں — کیا — تم — نصیحت — نہیں لیتے — یعنی اگر — میں — مؤمنوں — کو دھکیل دوں — کون اللہ کے مقابلے میں — میری مدد — کرے گا؛ کیا — تم نصیحت — نہیں لیتے۔
۳۔ عملی سبق: مفلس مؤمن — بھی — اللہ کو محبوب — ہیں؛ توہین — نہیں کرنی چاہیے۔"""
),
}
